from ...templatesession import new_session
from .base_btssm import BaseBtssmInterface


class BtssmUtilitiesInterface(BaseBtssmInterface):
    """ Miscellaneous commands that has something to do with BTSSM itself and not CLI/TRS tools """

    def kill_sitemanager(self, **kwargs):
        """ Kills all running BTS Sitemanager process """

        alias = kwargs.get('alias')
        alias = alias.strip() if alias is not None else None
        config = self.command_store.get(alias).get_config()
        kill_commands = ["sudo pkill -f com.nokia.em.poseidon.PoseidonStarter", "sudo pkill -f com.nokia.em.sitemgr.SitemgrStarter"]
        with new_session.NewSession(alias, config) as session:
            for cmd in kill_commands:
                session.executor.run_ignoring_rc(cmd)
